<!-- 动画工作室：编辑动画、控制器、骨架与时间轴，并管理预览、草稿和资源保存。 -->
<template>
  <section ref="studioRoot" class="animation-studio" :style="studioLayout" :data-preview-active="previewActive" tabindex="0" @keydown="onKeyDown">
    <header class="studio-toolbar">
      <details data-ui-motion-popover v-transient-popover class="create-menu"><summary :title="t('add')" :aria-label="t('add')"><EditorIcon name="add" /></summary><div class="create-choices">
        <button @click="newAsset('animation')">{{ t('animationClip') }}</button><button @click="newAsset('controller')">{{ t('animatorController') }}</button><button @click="newAsset('rig')">{{ t('rig') }}</button><button @click="newAsset('skin')">{{ t('skin') }}</button><button @click="newAsset('timeline')">{{ t('timeline') }}</button><button @click="newAsset('animationMask')">{{ t('animationMask') }}</button>
      </div></details>
      <select :aria-label="t('selectAnimationAsset')" v-model="selectedGuid" class="asset-select">
        <option value="">{{ t('selectAnimationAsset') }}</option>
        <option v-for="asset in studioAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option>
      </select>
      <span class="toolbar-spacer"></span>
      <UiButton icon="save" :label="t('saveAsset')" :disabled="!document || previewActive" @click="save" />
    </header>

    <div v-if="document" class="authoring-status" :data-draft-dirty="draftDirty">
      <strong>{{ previewActive ? copy.preview : draftDirty ? copy.dirty : copy.draft }}</strong>
      <details data-ui-motion-disclosure v-if="selectedAsset" class="binding-details"><summary>{{ copy.asset }} · {{ selectedAsset.name }}</summary><code>{{ selectedAsset.path }}</code><code v-if="activeTrack">{{ targetName(activeTrack.targetEntityUuid) }} · {{ activeTrack.property }}</code><code v-if="activeTimelineClip">{{ activeTimelineClip.id }} · {{ activeTimelineClip.asset ?? activeTimelineClip.targetEntityUuid }}</code></details>
      <span v-if="draftConflict" class="draft-error" role="alert">{{ copy.conflict }}</span>
      <button v-if="draftDirty" :disabled="previewActive" @click="discardDraft">{{ copy.discard }}</button>
      <template v-if="clip || controller || timeline"><button :disabled="previewBusy" @click="togglePreview">{{ previewActive ? (studio.previewPlaying ? t('pause') : t('play')) : copy.preview }}</button><button v-if="previewActive" @click="stopPreview()">{{ copy.stopPreview }}</button><label v-if="previewActive && !controller">{{ copy.runtimeTime }}<input v-model.number="studio.playhead" type="number" min="0" :step="frameStep" @change="seekPreview"></label></template>
      <template v-if="previewActive && timeline"><button @click="skipTimeline"><EditorIcon name="step" /> {{ t('skip') }}</button><button @click="resumeTimeline"><EditorIcon name="undo" /> {{ t('resume') }}</button></template><button v-if="previewActive" :class="{record:runtimeRecording.active}" @click="toggleRuntimeRecording">{{ runtimeRecording.active ? t('stopRecording') : t('runtimeRecording') }} · {{ runtimeRecording.samples }}</button><p v-if="runtimeRecording.limited">{{ copy.recordingLimit }}</p><UiButton @click="resetPaneSizes" icon="reset" :label="copy.resetLayout" />
      <p v-if="status" role="status">{{ status }}</p><p v-if="studio.recordMode">{{ copy.recordHint }}</p><p v-if="studio.recordIssue" class="draft-error" role="alert">{{ copy.recordRefused }} <code>{{ studio.recordIssue }}</code></p>
      <details data-ui-motion-disclosure v-if="draftInspection.issues.length"><summary>{{ copy.validation }} ({{ draftInspection.issues.length }})</summary><p v-for="issue in draftInspection.issues.slice(0,100)" :key="issue.path+issue.code"><code>{{ issue.path }}</code> · {{ copy.normalized }} · {{ issue.message }}</p></details>
    </div>
    <UiTabs v-if="document" class="studio-modes" :aria-label="t('animationWorkspace')" :model-value="studio.view" :items="visibleModes.map(mode => ({ id: mode.id, label: t(mode.label) }))" @update:model-value="studio.view = $event as typeof studio.view" />

    <div v-if="clip && (studio.view === 'dope' || studio.view === 'curve')" class="clip-workspace" :inert="previewActive">
      <header class="transport">
        
        <button :class="{ active: studio.recordMode, record: studio.recordMode }" @click="studio.recordMode = !studio.recordMode"><EditorIcon name="record" /> {{ copy.recordDraft }}</button>
        <button :class="{ active: studio.snapEnabled }" @click="studio.snapEnabled = !studio.snapEnabled"><EditorIcon name="snap" /> {{ t('snap') }}</button>
        <label>{{ t('playhead') }} <input v-model.number="studio.playhead" type="number" min="0" :step="frameStep" @change="snapPlayhead"></label>
        <label>{{ copy.zoom }}<UiSlider v-model.number="pixelsPerSecond"  min="30" max="480" step="10" /></label><label>{{ t('frameRate') }} <input v-model.number="clip.frameRate" type="number" min="1" max="240"></label>
        <label>{{ t('speed') }} <input v-model.number="clip.playbackSpeed" type="number" min="0.001" max="100" step="0.1"></label>
        <label>{{ t('loop') }} <input v-model="clip.loop" type="checkbox"></label>
        <label>{{ t('onionSkin') }} <input v-model="clip.onionSkin" type="checkbox"></label>
        <select :aria-label="t('tangentMode')" v-model="selectedTangent" :disabled="!selectedKeys.length" @change="applyTangent"><option v-for="mode in tangentModes" :key="mode">{{ mode }}</option></select>
        <UiButton :disabled="!selectedKeys.length" @click="copyKeys" icon="copy" :label="t('copy')" />
        <UiButton :disabled="!keyClipboard.length" @click="pasteKeys" icon="paste" :label="t('paste')" />
        <button @click="editingToolsOpen = !editingToolsOpen">{{ t('editingTools') }}</button>
      </header>
      <aside class="track-list"><PanelResizeHandle v-model="structureWidth" orientation="vertical" :minimum="160" :maximum="structureMaximum" :reset-value="220" :label="copy.resizeStructure" style="right:0;top:0;bottom:0" /><div ref="structurePane" class="track-list-scroll" @scroll="syncTrackScroll">
        <header><strong>{{ t('tracks') }}</strong><button :aria-label="t('add') + ' · ' + t('track')" @click="addTrack"><EditorIcon name="add" /></button></header>
        <button v-for="(track, index) in clip.tracks" :key="trackId(track, index)" class="numeric-track" :class="{ active: selectedTrack === index }" @click="selectedTrack = index">
          <span>{{ targetName(track.targetEntityUuid) }}</span><strong>{{ track.property }}</strong><small>{{ track.keyframes.length }} {{ t('keys') }}</small>
        </button>
        <button class="special-track" @click="addEvent"><EditorIcon name="flag" /> {{ t('animationEvents') }} ({{ clip.events.length }})</button>
        <button class="special-track" @click="addMarker"><EditorIcon name="animation" /> {{ t('markers') }} ({{ clip.markers.length }})</button>
        <button class="special-track" @click="addCommandTrack('Method')"><EditorIcon name="code" /> {{ t('methodTrack') }}</button>
        <button class="special-track" @click="addCommandTrack('Audio')"><EditorIcon name="audio" /> {{ t('audioTrack') }}</button>
        <button class="special-track" @click="addCommandTrack('NestedAnimation')"><EditorIcon name="animation" /> {{ t('nestedAnimationTrack') }}</button>
        <button class="special-track" @click="addCommandTrack('Timeline')"><EditorIcon name="link" /> {{ t('timeline') }}</button>
        <button class="special-track" @click="addCommandTrack('VisualGraph')"><EditorIcon name="graph" /> {{ t('visualGraph') }}</button>
        <button class="special-track" @click="addCommandTrack('Custom')"><EditorIcon name="graph" /> {{ t('customTrack') }}</button>
        <button class="special-track" @click="addSpriteFrame"><EditorIcon name="assets" /> {{ t('spriteFrames') }} ({{ clip.spriteFrames.length }})</button>
      </div></aside>

      <main v-if="studio.view === 'dope'" ref="dopePane" class="dope-sheet" @scroll="syncTrackScroll" @pointerdown.self="beginBoxSelection" @pointermove="moveBoxSelection" @pointerup="finishBoxSelection">
        <div class="time-ruler" :style="timelineWidthStyle">
          <i v-for="tick in rulerTicks" :key="tick" :style="{ left: `${timeToPixel(tick)}px` }">{{ formatTime(tick) }}</i>
          <b class="playhead" :style="{ left: `${timeToPixel(studio.playhead)}px` }"></b>
        </div>
        <div class="track-lanes" :style="timelineWidthStyle">
          <article v-for="(track, trackIndex) in clip.tracks" :key="trackId(track, trackIndex)" class="track-lane" :style="{height:(trackRowHeights[trackIndex] ?? 64)+'px'}">
            <button v-for="(keyframe, keyIndex) in track.keyframes" :key="keyId(trackIndex, keyIndex)" class="key-dot" :class="{ selected: isKeySelected(trackIndex, keyIndex) }" :style="{ left: `${timeToPixel(keyframe.time)}px` }" :title="`${keyframe.value} @ ${formatTime(keyframe.time)}`" @click.stop="onKeyClick(trackIndex, keyIndex, $event)" @pointerdown.stop="beginKeyDrag(trackIndex, keyIndex, $event)"></button>
          </article>
          <article class="event-lane"><button v-for="(event, index) in clip.events" :key="index" class="event-key" :style="{ left: `${timeToPixel(event.time)}px` }" :title="event.signal" @click="studio.playhead = event.time"><EditorIcon name="flag" /></button></article>
        </div>
        <div v-if="selectionBox" class="selection-box" :style="boxStyle"></div>
      </main>

      <main v-else class="curve-editor">
        <svg v-if="activeTrack" viewBox="0 0 1000 400" preserveAspectRatio="none" @pointerdown="curvePointer">
          <g class="curve-grid"><line v-for="x in 11" :key="`x${x}`" :x1="(x-1)*100" y1="0" :x2="(x-1)*100" y2="400"/><line v-for="y in 9" :key="`y${y}`" x1="0" :y1="(y-1)*50" x2="1000" :y2="(y-1)*50"/></g>
          <g v-if="clip.onionSkin" class="onion-skin"><circle v-for="sample in onionSamples" :key="sample.time" :cx="curveX(sample.time)" :cy="curveY(sample.value)" r="9"/><line v-for="sample in onionSamples" :key="`line-${sample.time}`" :x1="curveX(sample.time)" y1="0" :x2="curveX(sample.time)" y2="400"/></g>
          <polyline :points="curvePoints" />
          <circle v-for="(keyframe, index) in activeTrack.keyframes" role="button" tabindex="0" :aria-label="`${t('keyframe')} ${index+1}: ${keyframe.value} @ ${formatTime(keyframe.time)}`" @keydown.enter.prevent="selectKey(selectedTrack,index,$event)" @keydown.space.prevent="selectKey(selectedTrack,index,$event)" :key="index" :cx="curveX(keyframe.time)" :cy="curveY(keyframe.value)" r="6" :class="{ selected: isKeySelected(selectedTrack, index) }" @click.stop="selectKey(selectedTrack, index, $event)" />
        </svg>
        <aside v-if="selectedKeys[0]" class="key-inspector">
          <strong>{{ t('keyframe') }}</strong>
          <label>{{ t('keyframeTime') }}<input v-model.number="selectedKeys[0].keyframe.time" @change="sortTrackKeys" type="number" min="0" :step="frameStep"></label>
          <label>{{ t('keyframeValue') }}<input v-model.number="selectedKeys[0].keyframe.value" type="number" step="0.01"></label>
          <label>{{ t('tangentMode') }}<select v-model="selectedKeys[0].keyframe.tangentMode"><option v-for="mode in tangentModes" :key="mode">{{ mode }}</option></select></label>
          <label>{{ t('interpolation') }}<select v-model="selectedKeys[0].keyframe.interpolation"><option v-for="mode in interpolationModes" :key="mode">{{ mode }}</option></select></label>
          <label>{{ t('easing') }}<select v-model="selectedKeys[0].keyframe.easing"><option v-for="mode in easingModes" :key="mode">{{ mode }}</option></select></label>
          <label v-if="selectedKeys[0].keyframe.tangentMode === 'Free'">{{ t('tangents') }}<span><input :aria-label="t('input') + ' · ' + t('tangents')" v-model.number="selectedKeys[0].keyframe.inTangent" type="number" step="0.1"><input :aria-label="t('output') + ' · ' + t('tangents')" v-model.number="selectedKeys[0].keyframe.outTangent" type="number" step="0.1"></span></label>
        </aside>
      </main>

      <aside class="clip-inspector"><PanelResizeHandle v-if="!propertiesStacked" v-model="propertiesWidth" orientation="vertical" :minimum="220" :maximum="propertiesMaximum" :reset-value="320" reverse :label="copy.resizeProperties" style="left:0;top:0;bottom:0" /><PanelResizeHandle v-else v-model="propertiesHeight" orientation="horizontal" :minimum="160" :maximum="600" :reset-value="320" reverse :label="copy.resizeProperties" style="left:0;top:0;right:0" />
        <details data-ui-motion-disclosure v-if="editingToolsOpen" open class="editing-tools"><summary>{{ t('editingTools') }}</summary><label>{{ t('range') }}<span><input :aria-label="t('range') + ' · ' + t('start')" v-model.number="editRangeStart" type="number" min="0" step="0.01"><input :aria-label="t('range') + ' · ' + panelControlLabel('end')" v-model.number="editRangeEnd" type="number" min="0" step="0.01"></span></label><label>{{ t('timeScale') }}<input v-model.number="editTimeScale" type="number" min="0.001" max="1000" step="0.1"></label><label>{{ t('ripple') }}<input v-model="editRipple" type="checkbox"></label><button @click="applyRetime">{{ t('retime') }}</button><label>{{ t('keyTolerance') }}<input v-model.number="keyTolerance" type="number" min="0" step="0.0001"></label><button @click="reduceKeys">{{ t('reduceKeys') }}</button><button @click="sliceClip">{{ t('sliceClip') }}</button></details>
        <template v-if="activeTrack">
          <strong>{{ t('track') }}</strong>
          <label>{{ t('property') }}<select v-model="activeTrack.property"><option v-for="property in properties" :key="property">{{ property }}</option></select></label>
          <label>{{ t('target') }}<select v-model="activeTrack.targetEntityUuid"><option :value="null">{{ t('animationOwner') }}</option><option v-for="entity in entities" :key="entity.uuid" :value="entity.uuid">{{ entity.name }}</option></select></label>
          <button @click="addKey(activeTrack)"><EditorIcon name="add" /> {{ t('keyframe') }}</button>
          <button class="danger" @click="removeActiveTrack"><EditorIcon name="remove" /> {{ t('track') }}</button>
        </template>
        <details data-ui-motion-disclosure :open="clip.events.length > 0"><summary>{{ t('animationEvents') }}</summary><label v-for="(event, index) in clip.events" :key="index" class="event-edit"><input :aria-label="t('animationEvents') + ' · ' + t('keyframeTime')" v-model.number="event.time" type="number" min="0" :step="frameStep"><input :aria-label="t('eventSignal')" v-model="event.signal"><input :aria-label="t('eventPayload')" v-model="event.payload"><button :aria-label="t('remove') + ' · ' + event.signal" @click="clip.events.splice(index,1)"><EditorIcon name="remove" /></button></label></details>
        <details data-ui-motion-disclosure :open="clip.markers.length > 0"><summary>{{ t('markers') }}</summary><label v-for="(marker, index) in clip.markers" :key="index" class="event-edit"><input :aria-label="t('marker') + ' · ' + t('keyframeTime')" v-model.number="marker.time" type="number" min="0" :step="frameStep"><input :aria-label="t('marker') + ' · ' + t('name')" v-model="marker.name"><span></span><button :aria-label="t('remove') + ' · ' + marker.name" @click="clip.markers.splice(index,1)"><EditorIcon name="remove" /></button></label></details>
        <details data-ui-motion-disclosure :open="clip.commandTracks.length > 0"><summary>{{ t('commandTracks') }}</summary><article v-for="(track, trackIndex) in clip.commandTracks" :key="trackIndex" class="command-track"><header><select :aria-label="panelControlLabel('trackKind')" v-model="track.kind"><option>Method</option><option>Audio</option><option>NestedAnimation</option><option>Timeline</option><option>VisualGraph</option><option>Custom</option></select><button :aria-label="t('add') + ' · ' + t('commandTracks')" @click="track.commands.push({time:studio.playhead,value:'',payload:''})"><EditorIcon name="add" /></button><button :aria-label="t('remove') + ' · ' + t('commandTracks')" @click="clip.commandTracks.splice(trackIndex,1)"><EditorIcon name="remove" /></button></header><label>{{ t('target') }}<select v-model="track.targetEntityUuid"><option :value="null">{{ t('animationOwner') }}</option><option v-for="entity in entities" :key="entity.uuid" :value="entity.uuid">{{ entity.name }}</option></select></label><label v-for="(command,index) in track.commands" :key="index" class="event-edit"><input :aria-label="t('commandTracks') + ' · ' + t('keyframeTime')" v-model.number="command.time" type="number" min="0" :step="frameStep"><input :aria-label="t('commandTracks') + ' · ' + t('value')" v-model="command.value"><input :aria-label="t('commandTracks') + ' · ' + t('eventPayload')" v-model="command.payload"><button :aria-label="t('remove') + ' · ' + command.value" @click="track.commands.splice(index,1)"><EditorIcon name="remove" /></button></label></article></details>
        <details data-ui-motion-disclosure :open="clip.spriteFrames.length > 0"><summary>{{ t('spriteFrames') }}</summary><label v-for="(frame, index) in clip.spriteFrames" :key="index" class="frame-edit"><select :aria-label="t('spriteFrames')" v-model="frame.spriteAsset"><option :value="null">{{ t('none') }}</option><option v-for="asset in imageAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select><input :aria-label="t('spriteFrames') + ' · ' + t('duration')" v-model.number="frame.duration" type="number" min="0.001" step="0.01"><button :aria-label="t('remove') + ' · ' + t('spriteFrames')" @click="clip.spriteFrames.splice(index,1)"><EditorIcon name="remove" /></button></label></details>
        <section class="root-motion-card"><strong>{{ t('rootMotionPreview') }}</strong><span>Δx {{ rootMotion.delta.x.toFixed(3) }} · Δy {{ rootMotion.delta.y.toFixed(3) }}</span><span>Δ° {{ (rootMotion.delta.rotation*180/Math.PI).toFixed(2) }} · {{ t('travelDistance') }} {{ rootMotion.distance.toFixed(3) }}</span><small>{{ rootMotion.samples }} {{ t('deterministicSamples') }}</small></section>
        <details data-ui-motion-disclosure :open="selectedAnimationIssues.length > 0"><summary>{{ t('validation') }} ({{ selectedAnimationIssues.length }})</summary><article v-for="issue in selectedAnimationIssues" :key="`${issue.code}:${issue.source}`" :class="['animation-issue',issue.severity]"><strong>{{ issue.code }}</strong><span>{{ issue.message }}</span><code>{{ issue.source }}</code></article><p v-if="!selectedAnimationIssues.length">{{ t('animationValidationPassed') }}</p></details>
      </aside>
    </div>

    <div v-else-if="controller" class="controller-workspace" :inert="previewActive">
      <aside class="controller-sidebar"><PanelResizeHandle v-model="structureWidth" orientation="vertical" :minimum="160" :maximum="structureMaximum" :reset-value="220" :label="copy.resizeStructure" style="right:0;top:0;bottom:0" />
        <header><strong>{{ t('layers') }}</strong><button :aria-label="t('add') + ' · ' + t('layer')" @click="addLayer"><EditorIcon name="add" /></button></header>
        <article v-for="(layer, index) in controller.layers" :key="layer.id" class="layer-card">
          <UiPropertyRow :label="t('layer') + ' · ' + t('name')" stacked><input v-model="layer.name"></UiPropertyRow>
          <UiPropertyRow :label="t('weight')" stacked><UiSlider :aria-label="t('weight') + ' · ' + layer.name" v-model.number="layer.weight" min="0" max="1" step="0.05" /></UiPropertyRow>
          <UiPropertyRow :label="t('animationMask')" stacked><select v-model="layer.maskAsset"><option :value="null">{{ t('noMask') }}</option><option v-for="asset in maskAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('additive')"><input v-model="layer.additive" type="checkbox"></UiPropertyRow>
          <!-- A layer cannot synchronize to itself. -->
          <UiPropertyRow :label="t('synchronizedLayer')" stacked><select v-model="layer.synchronizedLayer"><option :value="null">{{ t('none') }}</option><option v-for="candidate in controller.layers.filter(candidate=>candidate.id!==layer.id)" :key="candidate.id" :value="candidate.id">{{ candidate.name }}</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('synchronizedTiming')"><input v-model="layer.synchronizedTiming" type="checkbox"></UiPropertyRow>
          <UiButton v-if="index" icon="remove" :label="t('remove') + ' · ' + layer.name" @click="controller.layers.splice(index,1)" />
        </article>
        <header><strong>{{ t('parameters') }}</strong><button :aria-label="t('add') + ' · ' + t('parameter')" @click="addParameter"><EditorIcon name="add" /></button></header>
        <label v-for="(parameter,index) in controller.parameters" :key="index" class="parameter-row"><input :aria-label="t('parameter') + ' · ' + t('name')" v-model="parameter.name"><select :aria-label="panelControlLabel('type')" v-model="parameter.type"><option>Bool</option><option>Float</option><option>Integer</option><option>Trigger</option></select><input :aria-label="t('defaultValue') + ' · ' + parameter.name" v-if="parameter.type === 'Float' || parameter.type === 'Integer'" v-model.number="parameter.defaultValue" type="number"><input :aria-label="t('defaultValue') + ' · ' + parameter.name" v-else v-model="parameter.defaultValue" type="checkbox"><button :aria-label="t('remove') + ' · ' + parameter.name" @click="controller.parameters.splice(index,1)"><EditorIcon name="remove" /></button></label>
      </aside>
      <main class="state-machine">
        <svg aria-hidden="true"><line v-for="transition in controller.transitions" :key="transition.id" v-bind="transitionLine(transition)"/></svg>
        <button v-for="state in controller.states" :key="state.id" :class="['state-node',{ selected:selectedStateId===state.id, default:controller.defaultState===state.id }]" :style="{left:`${state.x}px`,top:`${state.y}px`}" @click="selectedStateId=state.id">{{ state.name }}<small v-if="state.blendTree">{{ t('blendTree') }}</small></button>
        <UiButton class="add-state" icon="add" @click="addState">{{ t('state') }}</UiButton>
      </main>
      <aside class="state-inspector"><PanelResizeHandle v-if="!propertiesStacked" v-model="propertiesWidth" orientation="vertical" :minimum="220" :maximum="propertiesMaximum" :reset-value="320" reverse :label="copy.resizeProperties" style="left:0;top:0;bottom:0" /><PanelResizeHandle v-else v-model="propertiesHeight" orientation="horizontal" :minimum="160" :maximum="600" :reset-value="320" reverse :label="copy.resizeProperties" style="left:0;top:0;right:0" />
        <template v-if="selectedState">
          <label>{{ t('stateName') }}<input v-model="selectedState.name"></label>
          <label>{{ t('subgraph') }}<input v-model="selectedState.subgraph"></label>
          <label>{{ t('animationClip') }}<select v-model="selectedState.clipAsset"><option :value="null">{{ t('none') }}</option><option v-for="asset in clipAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
          <label>{{ t('speed') }}<input v-model.number="selectedState.speed" type="number" step="0.1"></label>
          <label>{{ t('speedParameter') }}<select v-model="selectedState.speedParameter"><option :value="null">{{ t('none') }}</option><option v-for="parameter in numericParameters" :key="parameter.name" :value="parameter.name">{{ parameter.name }}</option></select></label>
          <label>{{ t('cycleOffset') }}<input v-model.number="selectedState.cycleOffset" type="number" min="0" max="1" step=".01"></label>
          <label>{{ t('rootMotion') }}<select v-model="selectedState.rootMotion"><option>Apply</option><option>Ignore</option></select></label>
          <label class="inline-options"><span>{{ t('mirrorX') }} <input :aria-label="t('mirrorX')" v-model="selectedState.mirrorX" type="checkbox"></span><span>{{ t('mirrorY') }} <input :aria-label="t('mirrorY')" v-model="selectedState.mirrorY" type="checkbox"></span></label>
          <button @click="toggleBlendTree">{{ selectedState.blendTree ? t('removeBlendTree') : t('addBlendTree') }}</button>
