  try{const started=await previewSession.start(kind,assetReference(record.uuid),target.uuid,/* 先计算 loadedRecord.value===record&&draftText.value===source；仅当其为真值时求右侧 !draftDirty.value，返回短路求值结果。 */ ()=>loadedRecord.value===record&&draftText.value===source&&!draftDirty.value,selectedStateId.value);previewActive.value=started;studio.previewPlaying=started;status.value=started?copy.value.previewHint:''}catch(error){status.value=error instanceof Error?error.message:String(error)}finally{previewBusy.value=false}
}
/** 吸附播放头并定位预览，会话无法定位时显示目标提示。 */ function seekPreview(){snapPlayhead();if(previewActive.value&&!previewSession.seek(studio.playhead))status.value=copy.value.selectTarget}
let studioObserver:ResizeObserver|null=null,measuring=false
/** 测量工作区宽度和轨道行高，并观测轨道尺寸变化。 */ function measureStudio(){if(measuring)return;measuring=true;const root=studioRoot.value;if(root){availableWidth.value=root.clientWidth;const rows=Array.from(root.querySelectorAll<HTMLElement>('.track-list .numeric-track'));trackRowHeights.value=rows.map(/* 返回 row.offsetHeight 的当前值。 */ row=>row.offsetHeight);for(const row of rows)studioObserver?.observe(row)}measuring=false}
/** 同步结构栏与关键帧栏垂直滚动，避免细小误差反复触发。 */ function syncTrackScroll(event:Event){const target=event.currentTarget as HTMLElement,other=target===structurePane.value?dopePane.value:structurePane.value;if(other&&Math.abs(other.scrollTop-target.scrollTop)>1)other.scrollTop=target.scrollTop}
onMounted(/** 挂载时观测工作区尺寸并立即测量。 */ ()=>{studioObserver=new ResizeObserver(measureStudio);if(studioRoot.value)studioObserver.observe(studioRoot.value);measureStudio()})
onDeactivated(()=>{studioActive=false;retainDraft();stopPreview(false);studio.recordMode=false;cancelKeyDrag();setOpenAnimationRecordingDocument('',null)})
onActivated(()=>{studioActive=true;setOpenAnimationRecordingDocument(selectedGuid.value,clip.value,baseSource.value,baseline.value);void nextTick(measureStudio)})
onBeforeUnmount(/** 卸载前保留草稿、停止预览并清理会话、计时器、尺寸监听和拖动。 */ ()=>{retainDraft();stopPreview(false);previewSession.dispose();unregisterDraftOwner();window.clearInterval(inspectionTimer);studioObserver?.disconnect();cancelKeyDrag();setOpenAnimationRecordingDocument('',null)})
/** 按类型创建动画资源并选中，记录创建历史。 */ function newAsset(type:StudioAssetType){const asset=type==='animation'?createAnimationClipAsset(t('newAnimationName')):type==='controller'?createAnimatorControllerAsset(t('newControllerName')):type==='animationMask'?createAnimationMaskAsset(t('newMaskName')):type==='rig'?createRigAsset(t('newRigName')):type==='skin'?createSkinAsset(t('newSkinName')):createTimelineAsset(t('newTimelineName'));selectedGuid.value=asset.uuid;assetState.selectedGuid=asset.uuid;pushHistory(`Create ${type}`)}
/** 拒绝缺失、预览中、冲突或无效草稿；成功保存规范文档后清理恢复并更新基线和历史。 */ function save():boolean{const record=loadedRecord.value;if(!record||!document.value||!assetState.records.includes(record)){status.value=copy.value.missing;return false}if(previewActive.value||draftConflict.value){status.value=draftConflict.value?copy.value.conflict:copy.value.stopPreview;return false}const inspection=draftInspection.value;if(!inspection.normalized||inspection.issues.length){status.value=copy.value.invalid;return false}try{if(!updateTextAsset(record.uuid,JSON.stringify(inspection.normalized,null,2)))throw new Error(copy.value.failed);baseSource.value=readTextAsset(record.uuid);const view=studio.view;assignDocument(record.assetType as StudioAssetType,inspection.normalized);studio.view=view;studio.selectedKeyIds.splice(0);baseline.value=draftText.value;clearStudioDraft(record,draftProjectId);setOpenAnimationRecordingDocument(record.uuid,clip.value,baseSource.value,baseline.value);pushHistory('Edit animation asset',`animation:${record.uuid}`);status.value=copy.value.saved;addEditorLog(t('animationSaved',{name:record.name}),'Editor');return true}catch(error){status.value=error instanceof Error?error.message:copy.value.failed;return false}}
/** 为当前实体位置横轴添加带初始关键帧的动画轨道。 */ function addTrack(){clip.value?.tracks.push({property:'Transform.position.x',targetEntityUuid:physicsState.world.entities.find(/* 比较 entity.id 与 physicsState.selectedEntityId，返回严格相等的判断结果。 */ entity=>entity.id===physicsState.selectedEntityId)?.uuid??null,keyframes:[newKey()]});selectedTrack.value=(clip.value?.tracks.length??1)-1}/** 在播放头位置创建带默认切线、缓动和插值方式的关键帧。 */ function newKey():AnimationKeyframe{return{time:studio.snapEnabled?Math.round(studio.playhead/frameStep.value)*frameStep.value:studio.playhead,value:0,tangentMode:'Auto',inTangent:0,outTangent:0,easing:'Linear',interpolation:'Cubic'}}/** 追加默认关键帧后按时间排序。 */ function addKey(track:AnimationTrack){track.keyframes.push(newKey());track.keyframes.sort(/* 计算表达式 a.time-b.time 并返回结果，沿用操作数的原有类型规则。 */ (a,b)=>a.time-b.time)}/** 删除当前轨道并将选择回退到前一有效位置。 */ function removeActiveTrack(){clip.value?.tracks.splice(selectedTrack.value,1);selectedTrack.value=Math.max(0,selectedTrack.value-1)}/** 在播放头添加默认动画信号事件。 */ function addEvent(){clip.value?.events.push({time:studio.playhead,signal:'animation.event',payload:''})}/** 在播放头添加带顺序名称的动画标记。 */ function addMarker(){clip.value?.markers.push({time:studio.playhead,name:`Marker ${(clip.value?.markers.length??0)+1}`})}/** 添加指定类型的命令轨道及播放头处初始命令。 */ function addCommandTrack(kind:AnimationCommandKind){clip.value?.commandTracks.push({kind,targetEntityUuid:null,commands:[{time:studio.playhead,value:'',payload:''}]})}/** 添加持续一帧的空精灵帧。 */ function addSpriteFrame(){clip.value?.spriteFrames.push({spriteAsset:null,duration:frameStep.value})}
/** 按范围、时间比例和波纹选项重定时动画。 */ function applyRetime(){if(clip.value)clip.value=retimeAnimationClip(clip.value,editRangeStart.value,editRangeEnd.value,editTimeScale.value,editRipple.value)}/** 按容差对片段中每条轨道执行关键帧约减。 */ function reduceKeys(){if(!clip.value)return;clip.value.tracks.forEach(/** 用容差约减结果替换该轨道关键帧。 */ track=>track.keyframes=reduceAnimationKeys(track.keyframes,keyTolerance.value))}/** 按编辑范围截取当前动画片段。 */ function sliceClip(){if(clip.value)clip.value=sliceAnimationClip(clip.value,editRangeStart.value,editRangeEnd.value)}
/** 由轨道及关键帧索引生成选择标识。 */ function keyId(track:number,key:number){return`${track}:${key}`}/** 由目标、属性和索引生成轨道标识。 */ function trackId(track:AnimationTrack,index:number){return`${track.targetEntityUuid??'owner'}:${track.property}:${index}`}/* 调用 studio.selectedKeyIds.includes(keyId(track,key)) 并返回调用结果。 */ function isKeySelected(track:number,key:number){return studio.selectedKeyIds.includes(keyId(track,key))}/** 按修饰键替换或切换关键帧选择，并同步当前轨道与切线模式。 */ function selectKey(track:number,key:number,event:MouseEvent|PointerEvent|KeyboardEvent){const id=keyId(track,key);if(!(event.ctrlKey||event.metaKey||event.shiftKey))studio.selectedKeyIds.splice(0);if(studio.selectedKeyIds.includes(id))studio.selectedKeyIds.splice(studio.selectedKeyIds.indexOf(id),1);else studio.selectedKeyIds.push(id);selectedTrack.value=track;selectedTangent.value=clip.value!.tracks[track].keyframes[key].tangentMode}
/** 深复制选中关键帧到内部剪贴板。 */ function copyKeys(){keyClipboard.value=selectedKeys.value.map(/** 通过序列化复制关键帧，避免剪贴板引用原对象。 */ item=>JSON.parse(JSON.stringify(item.keyframe)) as AnimationKeyframe)}/** 以播放头对齐剪贴板最早关键帧，粘贴到当前轨道并排序。 */ function pasteKeys(){const track=activeTrack.value;if(!track)return;const start=Math.min(...keyClipboard.value.map(/* 返回 key.time 的当前值。 */ key=>key.time));for(const source of keyClipboard.value)track.keyframes.push({...source,time:studio.playhead+source.time-start});track.keyframes.sort(/* 计算表达式 a.time-b.time 并返回结果，沿用操作数的原有类型规则。 */ (a,b)=>a.time-b.time)}/** 为所有选中关键帧应用当前切线模式。 */ function applyTangent(){selectedKeys.value.forEach(/** 将选中关键帧的切线模式更新为面板所选值。 */ item=>item.keyframe.tangentMode=selectedTangent.value)}/** 开始关键帧拖动时保存文档、原时间和显示缩放，捕获指针并安装结束监听。 */ function beginKeyDrag(track:number,key:number,event:PointerEvent){if(event.button!==0||!clip.value)return;event.preventDefault();const element=event.currentTarget as HTMLElement,rect=dopePane.value?.getBoundingClientRect();selectKey(track,key,event);element.focus();keyDrag.value={track,key,startX:event.clientX,startTime:clip.value.tracks[track].keyframes[key].time,scale:rect&&dopePane.value?rect.width/dopePane.value.offsetWidth:1,pointerId:event.pointerId,element,document:clip.value};element.setPointerCapture(event.pointerId);window.addEventListener('pointermove',moveKeyDrag);window.addEventListener('pointerup',finishKeyDrag);window.addEventListener('pointercancel',cancelKeyDrag);window.addEventListener('keydown',keyDragKeydown);element.addEventListener('lostpointercapture',cancelKeyDrag)}
/** 仅处理所属指针和原文档的拖动，换算时间并按需吸附及限制非负。 */ function moveKeyDrag(event:PointerEvent){const drag=keyDrag.value;if(!drag||event.pointerId!==drag.pointerId||clip.value!==drag.document)return;let time=drag.startTime+(event.clientX-drag.startX)/(Math.max(.01,drag.scale)*pixelsPerSecond.value);if(studio.snapEnabled)time=Math.round(time/frameStep.value)*frameStep.value;drag.document.tracks[drag.track].keyframes[drag.key].time=Math.max(0,time)}
/** 拖动时按退出键取消并阻止事件继续传播。 */ function keyDragKeydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();cancelKeyDrag()}}
/** 取消拖动时恢复原关键帧时间，再统一清理拖动状态。 */ function cancelKeyDrag(){const drag=keyDrag.value;if(drag&&clip.value===drag.document)drag.document.tracks[drag.track]?.keyframes[drag.key]&&(drag.document.tracks[drag.track].keyframes[drag.key].time=drag.startTime);finishKeyDrag()}
/** 解除全部拖动监听和指针捕获，并重新排序文档轨道关键帧。 */ function finishKeyDrag(){const drag=keyDrag.value;keyDrag.value=null;window.removeEventListener('pointermove',moveKeyDrag);window.removeEventListener('pointerup',finishKeyDrag);window.removeEventListener('pointercancel',cancelKeyDrag);window.removeEventListener('keydown',keyDragKeydown);if(drag){drag.element.removeEventListener('lostpointercapture',cancelKeyDrag);if(drag.element.hasPointerCapture(drag.pointerId))drag.element.releasePointerCapture(drag.pointerId);drag.document.tracks.forEach(/* 调用 track.keyframes.sort((a,b)=>a.time-b.time) 并返回调用结果。 */ track=>track.keyframes.sort(/* 计算表达式 a.time-b.time 并返回结果，沿用操作数的原有类型规则。 */ (a,b)=>a.time-b.time))}}
/** 把指针位置转换为考虑显示缩放和滚动的框选坐标。 */ function boxPoint(event:PointerEvent){const target=event.currentTarget as HTMLElement,rect=target.getBoundingClientRect(),scale=rect.width/target.offsetWidth;return{x:(event.clientX-rect.left)/scale+target.scrollLeft,y:(event.clientY-rect.top)/scale+target.scrollTop}}
/** 左键开始框选，清空原选择并捕获指针。 */ function beginBoxSelection(event:PointerEvent){if(event.button!==0)return;const point=boxPoint(event);selectionBox.value={x1:point.x,y1:point.y,x2:point.x,y2:point.y};studio.selectedKeyIds.splice(0);(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)}
/** 更新当前框选矩形终点。 */ function moveBoxSelection(event:PointerEvent){if(!selectionBox.value)return;const point=boxPoint(event);selectionBox.value.x2=point.x;selectionBox.value.y2=point.y}
/** 按实际轨道行高检查框选内关键帧，完成后清除框选矩形。 */ function finishBoxSelection(){const box=selectionBox.value;if(!box||!clip.value){selectionBox.value=null;return}const left=Math.min(box.x1,box.x2),right=Math.max(box.x1,box.x2),top=Math.min(box.y1,box.y2),bottom=Math.max(box.y1,box.y2);let offset=31;clip.value.tracks.forEach(/** 累计轨道行偏移，并检查该轨道各关键帧是否位于框选范围。 */ (track,ti)=>{const height=trackRowHeights.value[ti]??64,y=offset+height/2;track.keyframes.forEach(/** 关键帧横坐标与轨道中心落入选框时添加选择标识。 */ (key,ki)=>{const x=timeToPixel(key.time);if(x>=left&&x<=right&&y>=top&&y<=bottom)studio.selectedKeyIds.push(keyId(ti,ki))});offset+=height});selectionBox.value=null}
/** 忽略文本输入目标，处理关键帧复制、粘贴和按倒序索引删除。 */ function onKeyDown(event:KeyboardEvent){if(isEditableKeyboardTarget(event.target))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='c'){event.preventDefault();copyKeys()}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='v'){event.preventDefault();pasteKeys()}else if(event.key==='Delete'&&clip.value){for(const item of [...selectedKeys.value].sort(/* 计算表达式 b.key-a.key 并返回结果，沿用操作数的原有类型规则。 */ (a,b)=>b.key-a.key))clip.value.tracks[item.track].keyframes.splice(item.key,1);studio.selectedKeyIds.splice(0)}}/** 修正非法或负播放头时间，并按需吸附到帧间隔。 */ function snapPlayhead(){if(!Number.isFinite(studio.playhead)){studio.playhead=0;return}studio.playhead=Math.max(0,studio.playhead);if(studio.snapEnabled)studio.playhead=Math.round(studio.playhead/frameStep.value)*frameStep.value}/* 计算表达式 40+time*pixelsPerSecond.value 并返回结果，沿用操作数的原有类型规则。 */ function timeToPixel(time:number){return 40+time*pixelsPerSecond.value}/** 将时间格式化为最多三位小数的秒数。 */ function formatTime(time:number){return`${Number(time.toFixed(3))}s`}/** 解析目标实体名称，缺失目标和默认拥有者使用本地化提示。 */ function targetName(uuid:string|null){return uuid?entities.value.find(/* 比较 entity.uuid 与 uuid，返回严格相等的判断结果。 */ entity=>entity.uuid===uuid)?.name??t('missingTarget'):t('animationOwner')}/* 计算表达式 20+time/Math.max(frameStep.value,clipDuration.value)*960 并返回结果，沿用操作数的原有类型规则。 */ function curveX(time:number){return 20+time/Math.max(frameStep.value,clipDuration.value)*960}/* 计算表达式 380-(value-curveRange.value.min)/(curveRange.value.max-curveRange.value.min)*360 并返回结果，沿用操作数的原有类型规则。 */ function curveY(value:number){return 380-(value-curveRange.value.min)/(curveRange.value.max-curveRange.value.min)*360}/** 把曲线指针横坐标转换为播放头时间并执行帧吸附。 */ function curvePointer(event:PointerEvent){const svg=event.currentTarget as SVGSVGElement,rect=svg.getBoundingClientRect();studio.playhead=Math.max(0,((event.clientX-rect.left)/rect.width*1000-20)/960*clipDuration.value);snapPlayhead()}
/** 添加默认浮点控制器参数。 */ function addParameter(){controller.value?.parameters.push({name:`parameter_${(controller.value?.parameters.length??0)+1}`,type:'Float',defaultValue:0})}/** 添加使用控制器默认状态的动画层及默认权重和同步配置。 */ function addLayer(){if(!controller.value)return;controller.value.layers.push({id:`layer_${Date.now().toString(36)}`,name:`Layer ${controller.value.layers.length+1}`,defaultState:controller.value.defaultState,weight:1,additive:false,maskAsset:null,synchronizedLayer:null,synchronizedTiming:false})}/** 创建带默认播放设置和网格位置的控制器状态并选中。 */ function addState(){const value=controller.value;if(!value)return;const id=`state_${Date.now().toString(36)}`;value.states.push({id,name:`State ${value.states.length+1}`,clipAsset:null,speed:1,speedParameter:null,cycleOffset:0,mirrorX:false,mirrorY:false,rootMotion:'Apply',x:90+(value.states.length%4)*150,y:80+Math.floor(value.states.length/4)*90,subgraph:'Base',blendTree:null});selectedStateId.value=id}/** 保留至少一个状态；删除状态及关联转换，并修复层与控制器默认状态。 */ function removeState(){const value=controller.value,state=selectedState.value;if(!value||!state||value.states.length<=1)return;value.states=value.states.filter(/* 比较 item.id 与 state.id，返回严格不等的判断结果。 */ item=>item.id!==state.id);value.transitions=value.transitions.filter(/* 先计算 item.from!==state.id；仅当其为真值时求右侧 item.to!==state.id，返回短路求值结果。 */ item=>item.from!==state.id&&item.to!==state.id);value.layers.forEach(/** 层默认状态被删除时改为首个保留状态。 */ layer=>{if(layer.defaultState===state.id)layer.defaultState=value.states[0].id});if(value.defaultState===state.id)value.defaultState=value.states[0].id;selectedStateId.value=value.states[0].id}/** 在至少两个状态之间添加带退出时间的默认转换。 */ function addTransition(){const value=controller.value;if(!value||value.states.length<2)return;value.transitions.push({id:`transition_${Date.now().toString(36)}`,from:value.states[0].id,to:value.states[1].id,hasExitTime:true,exitTime:1,duration:.1,interruption:'SourceThenDestination',syncMode:'None',syncMarker:'',destinationOffset:0,conditions:[]})}/** 解析转换两端状态并计算连线端点，缺失位置按零处理。 */ function transitionLine(transition:AnimatorTransition){const value=controller.value??defaultAnimatorController(),from=value.states.find(/* 比较 state.id 与 transition.from，返回严格相等的判断结果。 */ state=>state.id===transition.from),to=value.states.find(/* 比较 state.id 与 transition.to，返回严格相等的判断结果。 */ state=>state.id===transition.to);return{x1:(from?.x??0)+55,y1:(from?.y??0)+18,x2:(to?.x??0)+55,y2:(to?.y??0)+18}}/** 切换状态的一维混合树，使用现有数字参数及当前片段初始化。 */ function toggleBlendTree(){const state=selectedState.value;if(!state)return;state.blendTree=state.blendTree?null:{type:'1D',parameter:numericParameters.value[0]?.name??'',parameterY:numericParameters.value[1]?.name??'',synchronizeNormalizedTime:true,children:[{clipAsset:state.clipAsset,threshold:0,positionX:0,positionY:0,speed:1}]} }/** 通过统一入口启动或暂停控制器预览。 */ function previewController(){void togglePreview()}
/** 已有录制时停止并提取；否则仅为有效预览目标开始运行时录制。 */ function toggleRuntimeRecording(){if(animationRuntime.recordingStatus().active){stopPreview();return}const target=previewSession.target;if(!target||!previewActive.value){status.value=copy.value.previewHint;return}animationRuntime.beginRuntimeRecording(target,clip.value?.frameRate??timeline.value?.frameRate??60,null)}
/** 以当前骨骼为父节点创建骨骼，同时登记默认重定向别名并选中。 */ function addBone(){if(!rig.value)return;const parent=selectedBone.value,id=`bone_${Date.now().toString(36)}`;rig.value.bones.push({id,name:`Bone ${rig.value.bones.length+1}`,parentId:parent?.id??null,position:{x:parent?.length??1,y:0},rotation:0,scale:{x:1,y:1},length:1});rig.value.retargetAliases[id]=id;selectedBoneId.value=id}/** 为当前骨骼创建默认两节逆向运动学链。 */ function addIk(){if(!rig.value||!selectedBone.value)return;const id=`ik_${Date.now().toString(36)}`;rig.value.ikChains.push({id,name:`IK ${rig.value.ikChains.length+1}`,endBoneId:selectedBone.value.id,chainLength:2,target:{x:2,y:0},weight:1,iterations:8});selectedIkId.value=id}/** 为当前骨骼添加默认旋转限制约束并选中。 */ function addConstraint(){if(!rig.value||!selectedBone.value)return;const id=`constraint_${Date.now().toString(36)}`;rig.value.constraints.push({id,boneId:selectedBone.value.id,type:'RotationLimit',targetBoneId:null,minimum:{x:-Math.PI,y:-1e6},maximum:{x:Math.PI,y:1e6},weight:1});selectedConstraintId.value=id}/** 为当前骨骼添加允许图像和预制体的附件插槽。 */ function addAttachment(){if(!rig.value||!selectedBone.value)return;const index=rig.value.attachments.length+1;rig.value.attachments.push({id:`attachment_${Date.now().toString(36)}`,name:`Attachment ${index}`,boneId:selectedBone.value.id,position:{x:0,y:0},rotation:0,allowedAssetTypes:['image','prefab']})}/** 替换当前骨骼别名，净化名称并限制为最多三十二项。 */ function setSelectedBoneAliases(event:Event){if(!rig.value||!selectedBone.value)return;for(const [alias,id] of Object.entries(rig.value.retargetAliases))if(id===selectedBone.value.id)delete rig.value.retargetAliases[alias];for(const alias of (event.target as HTMLInputElement).value.split(',').map(/* 调用 value.trim().replace(/[^a-zA-Z0-9_-]/g,'_') 并返回调用结果。 */ value=>value.trim().replace(/[^a-zA-Z0-9_-]/g,'_')).filter(Boolean).slice(0,32))rig.value.retargetAliases[alias]=selectedBone.value.id}/** 把骨骼平移、弧度旋转和缩放转换为 SVG 变换。 */ function boneTransform(bone:RigBone2D){return`translate(${bone.position.x} ${-bone.position.y}) ro